count = 0
for emo, svg in SVG_REPLACEMENTS.items():
    if emo in content:
        num = content.count(emo)
        content = content.replace(emo, svg)
        count += num
        print(f"Replaced {emo} ({num} times)")

with open(file_path, "w", encoding="utf-8") as f:
    f.write(content)

print(f"Total {count} emojis replaced with monochromatic line SVGs in templates/01-stay/index.html!")
